import React, { useEffect, useState, useMemo } from 'react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { Bell } from "lucide-react";
import { useDataState, useDataDispatch } from '../../contexts/DataContext';
import { useAuth } from '../../contexts/AuthContext';
import { Badge } from '../ui/badge';
import { Link } from 'react-router-dom';
import { format, isToday, isFuture, parseISO } from 'date-fns';
import { ScrollArea } from '../ui/scroll-area';
import { db, CustomerFeedback } from '../../lib/db';

export function AgentNotifications() {
  const { records } = useDataState();
  const { user } = useAuth();
  const [feedbacks, setFeedbacks] = useState<CustomerFeedback[]>([]);

  useEffect(() => {
      if (user) {
          db.customer_feedbacks.where('agentId').equals(user.id).toArray().then(fbs => {
              setFeedbacks(fbs);
          });
      }
  }, [user]);

  const notifications = useMemo(() => {
    if (!user || !records) return [];

    const agentFeedbacks = feedbacks;

    const ptpReminders = agentFeedbacks
      .filter(f => f.status === 'PTP' && f.ptpDate && (isToday(parseISO(f.ptpDate)) || isFuture(parseISO(f.ptpDate))))
      .map(f => ({
        type: 'PTP',
        feedback: f,
        customer: records.find((c: any) => c.agreementid === f.agreementid),
        date: f.ptpDate!,
      }));

    const cbReminders = agentFeedbacks
      .filter(f => f.status === 'CB' && f.cbDate && (isToday(parseISO(f.cbDate)) || isFuture(parseISO(f.cbDate))))
      .map(f => ({
        type: 'CB',
        feedback: f,
        customer: records.find((c: any) => c.agreementid === f.agreementid),
        date: f.cbDate!,
      }));

    return [...ptpReminders, ...cbReminders]
        .sort((a, b) => parseISO(a.date).getTime() - parseISO(b.date).getTime());

  }, [feedbacks, records, user]);

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="icon" className="relative text-muted-foreground hover:text-foreground">
          <Bell className="h-5 w-5" />
          {notifications.length > 0 && (
             <Badge variant="destructive" className="absolute -top-1 -right-1 h-5 w-5 flex items-center justify-center rounded-full p-0 text-[10px]">
                {notifications.length}
            </Badge>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-80">
        <DropdownMenuLabel>Reminders</DropdownMenuLabel>
        <DropdownMenuSeparator />
        <ScrollArea className="h-72">
            {notifications.length > 0 ? (
                notifications.map(({ type, feedback, customer, date }) => {
                  if (!customer) return null;
                  return (
                    <DropdownMenuItem key={feedback.id} asChild>
                        <Link to={`/customer/${customer?.agreementid}`} className="flex flex-col items-start gap-1 p-3 cursor-pointer">
                            <div className="flex justify-between w-full items-center">
                                <span className="font-semibold line-clamp-1">{customer?.customer_name || customer?.['Customer Name']}</span>
                                <Badge variant={type === 'PTP' ? 'default' : 'secondary'} className="ml-2">{type}</Badge>
                            </div>
                            <p className="text-xs text-muted-foreground">
                                {format(parseISO(date), "PPP 'at' p")}
                            </p>
                        </Link>
                    </DropdownMenuItem>
                  );
                })
            ) : (
                <p className="text-sm text-muted-foreground text-center p-4">No upcoming reminders.</p>
            )}
        </ScrollArea>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import React from 'react';

interface BucketBadgeProps {
  bkt: string | number;
  className?: string;
}

export function BucketBadge({ bkt, className = '' }: BucketBadgeProps) {
  const strBkt = String(bkt ?? '').trim();
  const num = Number(strBkt);

  if (strBkt.toUpperCase() === 'NPA' || strBkt.toUpperCase().includes('NPA')) {
    return (
      <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-bold border bg-rose-950/40 text-rose-400 border-rose-800/40 ${className}`}>
        <span className="h-1.5 w-1.5 rounded-full bg-rose-500 shrink-0"></span>
        <span>NPA</span>
      </span>
    );
  }

  if (isNaN(num) || strBkt === '' || strBkt === '-') {
    return (
      <span className={`inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-muted text-muted-foreground ${className}`}>
        -
      </span>
    );
  }

  if (num <= 1) {
    return (
      <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-bold border bg-yellow-500/10 text-yellow-600 dark:text-yellow-400 border-yellow-500/30 ${className}`}>
        <span className="h-1.5 w-1.5 rounded-full bg-yellow-500 shrink-0"></span>
        <span>● {num}</span>
      </span>
    );
  }

  if (num === 2) {
    return (
      <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-bold border bg-orange-500/10 text-orange-600 dark:text-orange-400 border-orange-500/30 ${className}`}>
        <span className="h-1.5 w-1.5 rounded-full bg-orange-500 shrink-0"></span>
        <span>● {num}</span>
      </span>
    );
  }

  return (
    <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-bold border bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/30 ${className}`}>
      <span className="h-1.5 w-1.5 rounded-full bg-red-500 shrink-0"></span>
      <span>● {num}</span>
    </span>
  );
}

export function getBucketRowBorder(bkt: string | number): string {
  const str = String(bkt ?? '').trim();
  const num = Number(str);
  if (str.toUpperCase().includes('NPA') || num >= 3) {
    return 'border-l-2 border-l-red-500';
  }
  if (num === 2) {
    return 'border-l-2 border-l-orange-500';
  }
  if (num <= 1 && !isNaN(num)) {
    return 'border-l-2 border-l-yellow-500';
  }
  return 'border-l-2 border-l-transparent';
}

