      </form>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { BackupSnapshotRecord } from '../../lib/db';
import { 
  Database, Download, Upload, ShieldCheck, 
  Trash2, RefreshCw, Clock, HardDrive, CheckCircle2, AlertCircle, FileJson 
} from 'lucide-react';
import { Button } from '../ui/button';
import { toast } from 'sonner';

interface BackupRecoverySectionProps {
  backups: BackupSnapshotRecord[];
  scheduleMinutes: number;
  onSetSchedule: (minutes: number) => void;
  onCreateBackup: (label?: string) => Promise<void>;
  onRestoreBackup: (payload: string, mode: 'MERGE' | 'REPLACE') => Promise<void>;
  onVerifyBackup: (backupId: string) => Promise<{ valid: boolean; details: string }>;
  onDownloadBackup: (backupId: string) => Promise<void>;
  onDeleteBackup: (backupId: string) => Promise<void>;
}

export function BackupRecoverySection({
  backups,
  scheduleMinutes,
  onSetSchedule,
  onCreateBackup,
  onRestoreBackup,
  onVerifyBackup,
  onDownloadBackup,
  onDeleteBackup,
}: BackupRecoverySectionProps) {
  const [isCreating, setIsCreating] = useState(false);
  const [backupLabel, setBackupLabel] = useState('');
  const [restoreMode, setRestoreMode] = useState<'MERGE' | 'REPLACE'>('MERGE');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleCreate = async () => {
    try {
      setIsCreating(true);
      await onCreateBackup(backupLabel.trim() || undefined);
      setBackupLabel('');
    } finally {
      setIsCreating(false);
    }
  };

  const handleVerify = async (id: string) => {
    const res = await onVerifyBackup(id);
    if (res.valid) {
      toast.success(res.details);
    } else {
      toast.error(res.details);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const content = event.target?.result as string;
      if (!content) return;
      if (confirm(`Restore data from file "${file.name}" in ${restoreMode} mode?`)) {
        await onRestoreBackup(content, restoreMode);
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6">
      {/* Top Action Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Create Manual Backup */}
        <div className="p-4 rounded-2xl bg-card border border-border shadow-xs space-y-3">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-primary/10 text-primary">
              <Database className="w-5 h-5" />
            </div>
            <div>
              <h4 className="text-sm font-bold text-foreground">Create Snapshot Now</h4>
              <p className="text-[11px] text-muted-foreground">Snapshot all CRM tables locally</p>
            </div>
          </div>
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="Optional label (e.g. Pre-Import)"
              value={backupLabel}
              onChange={(e) => setBackupLabel(e.target.value)}
              className="flex-1 px-3 py-1.5 rounded-lg border border-border bg-muted/40 text-xs"
            />
            <Button size="sm" onClick={handleCreate} disabled={isCreating} className="font-bold text-xs">
              {isCreating ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : 'Backup Now'}
            </Button>
          </div>
        </div>

        {/* Scheduled Backups */}
        <div className="p-4 rounded-2xl bg-card border border-border shadow-xs space-y-3">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
              <Clock className="w-5 h-5" />
            </div>
            <div>
              <h4 className="text-sm font-bold text-foreground">Automated Schedule</h4>
              <p className="text-[11px] text-muted-foreground">Recurring local snapshots</p>
            </div>
          </div>
          <select
            value={scheduleMinutes}
            onChange={(e) => onSetSchedule(parseInt(e.target.value, 10))}
            className="w-full px-3 py-2 rounded-lg border border-border bg-muted/40 text-xs font-semibold"
          >
            <option value="0">Disabled (Manual Only)</option>
            <option value="15">Every 15 Minutes (High Frequency)</option>
            <option value="60">Every 1 Hour (Recommended)</option>
            <option value="360">Every 6 Hours</option>
            <option value="1440">Daily (Every 24 Hours)</option>
          </select>
        </div>

        {/* Disaster Recovery Import */}
        <div className="p-4 rounded-2xl bg-card border border-border shadow-xs space-y-3">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-blue-500/10 text-blue-600 dark:text-blue-400">
              <HardDrive className="w-5 h-5" />
            </div>
            <div>
              <h4 className="text-sm font-bold text-foreground">External Drive Restore</h4>
              <p className="text-[11px] text-muted-foreground">Recover database from external file</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <select
              value={restoreMode}
              onChange={(e) => setRestoreMode(e.target.value as any)}
              className="px-2.5 py-1.5 rounded-lg border border-border bg-muted/40 text-[11px] font-semibold"
            >
              <option value="MERGE">Merge Mode</option>
              <option value="REPLACE">Clean Replace</option>
            </select>
            <input
              type="file"
              ref={fileInputRef}
              accept=".json"
              onChange={handleFileUpload}
              className="hidden"
            />
            <Button
              size="sm"
              variant="outline"
              className="flex-1 text-xs font-semibold"
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="w-3.5 h-3.5 mr-1" /> Choose File
            </Button>
          </div>
        </div>
      </div>

      {/* Backup History Table */}
      <div className="bg-card rounded-2xl border border-border overflow-hidden shadow-sm">
        <div className="p-4 border-b border-border flex items-center justify-between">
          <div>
            <h3 className="text-base font-bold text-foreground">Backup & Disaster Recovery History</h3>
            <p className="text-xs text-muted-foreground">Indexed local snapshots with SHA-256 cryptographic checksums</p>
          </div>
          <span className="text-xs font-semibold text-muted-foreground">
            {backups.length} Snapshots Available
          </span>
        </div>

        {backups.length === 0 ? (
          <div className="p-8 text-center text-xs text-muted-foreground">
            No backup snapshots generated yet. Click "Backup Now" above to create your first baseline snapshot.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead className="bg-muted/40 text-muted-foreground uppercase font-bold tracking-wider text-[10px] border-b border-border">
                <tr>
                  <th className="py-3 px-4">Backup Label / ID</th>
                  <th className="py-3 px-4">Created Date</th>
                  <th className="py-3 px-4">Type</th>
                  <th className="py-3 px-4">Records / Size</th>
                  <th className="py-3 px-4">Checksum</th>
                  <th className="py-3 px-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {backups.map(b => (
                  <tr key={b.id} className="hover:bg-muted/20 transition-colors">
                    <td className="py-3 px-4">
                      <div className="font-bold text-foreground">{b.label || b.id}</div>
                      <div className="text-[10px] text-muted-foreground font-mono">{b.id}</div>
                    </td>

                    <td className="py-3 px-4 text-muted-foreground">
                      {new Date(b.timestamp).toLocaleString()}
                    </td>

                    <td className="py-3 px-4">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${
                        b.type === 'SCHEDULED' ? 'bg-emerald-500/10 text-emerald-600' : 'bg-primary/10 text-primary'
                      }`}>
                        {b.type}
                      </span>
                    </td>

                    <td className="py-3 px-4 text-foreground">
                      <div className="font-semibold">{b.recordCounts?.records || 0} loans • {b.recordCounts?.feedbacks || 0} feedback</div>
                      <div className="text-[10px] text-muted-foreground font-mono">{(b.sizeBytes / 1024).toFixed(1)} KB</div>
                    </td>

                    <td className="py-3 px-4 font-mono text-[10px] text-primary">
                      {b.checksum}
                    </td>

                    <td className="py-3 px-4 text-right">
                      <div className="flex items-center justify-end gap-1">
                        <Button
                          size="sm"
                          variant="ghost"
                          className="h-7 text-xs text-muted-foreground hover:text-foreground"
                          title="Verify Integrity"
                          onClick={() => handleVerify(b.id)}
                        >
                          <ShieldCheck className="w-3.5 h-3.5 mr-1 text-emerald-500" /> Verify
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          className="h-7 text-xs text-muted-foreground hover:text-foreground"
                          title="Download to External Drive"
                          onClick={() => onDownloadBackup(b.id)}
                        >
                          <Download className="w-3.5 h-3.5 mr-1 text-blue-500" /> Export
                        </Button>
                        <Button
                          size="icon"
                          variant="ghost"
                          className="h-7 w-7 text-destructive hover:bg-destructive/10"
                          title="Delete Snapshot"
                          onClick={() => {
                            if (confirm('Delete this backup snapshot?')) {
                              onDeleteBackup(b.id);
                            }
                          }}
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { ConflictRecord } from '../../lib/sync/types';
import { 
  AlertTriangle, Check, ArrowRight, ShieldAlert, 
  Layers, GitMerge, FileText, CheckCircle2 
} from 'lucide-react';
import { Button } from '../ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '../ui/dialog';

interface ConflictResolverModalProps {
  conflicts: ConflictRecord[];
  onResolve: (
    conflictId: string,
    resolution: 'KEEP_LOCAL' | 'KEEP_REMOTE' | 'FIELD_MERGE' | 'MANUAL',
    customData?: any
  ) => void;
}

export function ConflictResolverModal({ conflicts, onResolve }: ConflictResolverModalProps) {
  const [selectedConflict, setSelectedConflict] = useState<ConflictRecord | null>(null);
  const [fieldSelections, setFieldSelections] = useState<Record<string, 'local' | 'remote'>>({});

  const handleOpenConflict = (c: ConflictRecord) => {
    setSelectedConflict(c);
    const initial: Record<string, 'local' | 'remote'> = {};
    c.fieldConflicts.forEach(f => {
      initial[f.field] = 'local';
    });
    setFieldSelections(initial);
  };

  const handleCustomMerge = () => {
    if (!selectedConflict) return;
    const merged = { ...selectedConflict.localData };
    selectedConflict.fieldConflicts.forEach(f => {
      if (fieldSelections[f.field] === 'remote') {
        merged[f.field] = selectedConflict.remoteData[f.field];
      }
    });
    onResolve(selectedConflict.id, 'MANUAL', merged);
    setSelectedConflict(null);
  };

  return (
    <div className="space-y-4">
      {conflicts.length === 0 ? (
        <div className="bg-card rounded-2xl border border-border p-8 text-center flex flex-col items-center justify-center">
          <div className="p-3 rounded-2xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 mb-3 border border-emerald-500/20">
            <CheckCircle2 className="w-8 h-8" />
          </div>
          <h3 className="text-base font-bold text-foreground mb-1">All Systems in Synchronization Harmony</h3>
          <p className="text-xs text-muted-foreground max-w-md">
            No concurrent data conflicts detected across connected peer terminals. All CRDT journals and deltas are cleanly resolved.
          </p>
        </div>
      ) : (
        <div className="bg-card rounded-2xl border border-amber-500/30 overflow-hidden shadow-sm">
          <div className="p-4 border-b border-border bg-amber-500/5 flex items-center justify-between">
            <div className="flex items-center gap-2.5">
              <div className="p-2 rounded-xl bg-amber-500/10 text-amber-600 border border-amber-500/20">
                <AlertTriangle className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-base font-bold text-foreground">
                  Detected Data Conflicts ({conflicts.length})
                </h3>
                <p className="text-xs text-muted-foreground">
                  Concurrent modifications require Administrator arbitration
                </p>
              </div>
            </div>
          </div>

          <div className="divide-y divide-border">
            {conflicts.map(c => (
              <div key={c.id} className="p-4 flex items-center justify-between flex-wrap gap-3 hover:bg-muted/20 transition-colors">
                <div>
                  <div className="flex items-center gap-2">
                    <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-primary/10 text-primary border border-primary/20 uppercase font-mono">
                      {c.tableName}
                    </span>
                    <span className="text-sm font-bold text-foreground">
                      Record: {c.recordId}
                    </span>
                  </div>
                  <div className="mt-1 text-xs text-muted-foreground flex items-center gap-3">
                    <span>Conflicting Fields: <strong>{c.fieldConflicts.map(f => f.field).join(', ')}</strong></span>
                    <span>•</span>
                    <span>Detected: {new Date(c.detectedAt).toLocaleTimeString()}</span>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    className="border-emerald-500/30 text-emerald-600 hover:bg-emerald-500/10 text-xs font-semibold"
                    onClick={() => onResolve(c.id, 'KEEP_LOCAL')}
                  >
                    Keep Local (This PC)
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    className="border-blue-500/30 text-blue-600 hover:bg-blue-500/10 text-xs font-semibold"
                    onClick={() => onResolve(c.id, 'KEEP_REMOTE')}
                  >
                    Keep Remote (Peer)
                  </Button>
                  <Button
                    size="sm"
                    className="bg-primary text-primary-foreground text-xs font-bold"
                    onClick={() => handleOpenConflict(c)}
                  >
                    <GitMerge className="w-3.5 h-3.5 mr-1.5" /> Diff & Merge
                  </Button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Side-by-Side Diff Resolution Modal */}
      <Dialog open={!!selectedConflict} onOpenChange={() => setSelectedConflict(null)}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-base">
              <GitMerge className="w-5 h-5 text-primary" />
              Conflict Diff & Field Merge Studio
            </DialogTitle>
            <DialogDescription>
              Compare divergent values from both systems and select which field value to keep for the master record.
            </DialogDescription>
          </DialogHeader>

          {selectedConflict && (
            <div className="space-y-5 text-xs">
              <div className="grid grid-cols-2 gap-4">
                {/* System A (Local) */}
                <div className="p-3.5 rounded-xl bg-card border-2 border-primary/30 space-y-2">
                  <div className="flex items-center justify-between pb-2 border-b border-border">
                    <span className="font-bold text-foreground">System A (Local Instance)</span>
                    <span className="text-[10px] text-muted-foreground">{new Date(selectedConflict.localTimestamp).toLocaleTimeString()}</span>
                  </div>
                  <p className="text-[11px] text-muted-foreground">Original terminal state on this host</p>
                </div>

                {/* System B (Remote) */}
                <div className="p-3.5 rounded-xl bg-card border-2 border-blue-500/30 space-y-2">
                  <div className="flex items-center justify-between pb-2 border-b border-border">
                    <span className="font-bold text-foreground">System B (Remote Peer: {selectedConflict.remotePeerId})</span>
                    <span className="text-[10px] text-muted-foreground">{new Date(selectedConflict.remoteTimestamp).toLocaleTimeString()}</span>
                  </div>
                  <p className="text-[11px] text-muted-foreground">Incoming change from mesh peer</p>
                </div>
              </div>

              {/* Field comparison table */}
              <div className="rounded-xl border border-border overflow-hidden">
                <table className="w-full text-left text-xs">
                  <thead className="bg-muted/50 uppercase font-bold text-[10px] text-muted-foreground border-b border-border">
                    <tr>
                      <th className="p-3">Field</th>
                      <th className="p-3">System A (Local)</th>
                      <th className="p-3">System B (Remote)</th>
                      <th className="p-3 text-right">Selected Source</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border">
                    {selectedConflict.fieldConflicts.map(fc => (
                      <tr key={fc.field} className="hover:bg-muted/20">
                        <td className="p-3 font-mono font-bold text-foreground">{fc.field}</td>
                        <td className="p-3 text-emerald-600 dark:text-emerald-400 font-semibold bg-emerald-500/5">
                          {String(fc.localVal ?? '-')}
                        </td>
                        <td className="p-3 text-blue-600 dark:text-blue-400 font-semibold bg-blue-500/5">
                          {String(fc.remoteVal ?? '-')}
                        </td>
                        <td className="p-3 text-right">
                          <div className="inline-flex rounded-lg border border-border p-0.5 bg-muted/40">
                            <button
                              onClick={() => setFieldSelections(prev => ({ ...prev, [fc.field]: 'local' }))}
                              className={`px-2.5 py-1 text-[10px] font-bold rounded-md transition-colors ${
                                fieldSelections[fc.field] === 'local'
                                  ? 'bg-card text-primary shadow-xs'
                                  : 'text-muted-foreground hover:text-foreground'
                              }`}
                            >
                              Keep A
                            </button>
                            <button
                              onClick={() => setFieldSelections(prev => ({ ...prev, [fc.field]: 'remote' }))}
                              className={`px-2.5 py-1 text-[10px] font-bold rounded-md transition-colors ${
                                fieldSelections[fc.field] === 'remote'
                                  ? 'bg-card text-blue-600 shadow-xs'
                                  : 'text-muted-foreground hover:text-foreground'
                              }`}
                            >
                              Keep B
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="flex items-center justify-between pt-2 border-t border-border">
                <Button variant="outline" size="sm" onClick={() => setSelectedConflict(null)}>
                  Cancel
                </Button>
                <div className="flex gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    className="border-emerald-500/30 text-emerald-600 hover:bg-emerald-500/10 text-xs font-bold"
                    onClick={() => {
                      onResolve(selectedConflict.id, 'KEEP_LOCAL');
                      setSelectedConflict(null);
                    }}
                  >
                    Keep All Local (A)
                  </Button>
                  <Button
                    size="sm"
                    className="bg-primary text-primary-foreground text-xs font-bold"
                    onClick={handleCustomMerge}
                  >
                    <Check className="w-3.5 h-3.5 mr-1.5" /> Apply Merged Record
                  </Button>
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

