import { createContext, useContext, useState, ReactNode, useEffect } from 'react';
import { User, Role, DEFAULT_PERMISSIONS } from '../constants/permissions';
import { db } from '../lib/db';
import { derivePasswordHash, verifyPassword } from '../lib/authCrypto';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (identifier: string, password: string) => Promise<User>;
  logout: () => void;
  hasPermission: (view: string) => boolean;
  isExecutive: () => boolean;
  users: User[];
  addUser: (u: Omit<User, 'id'> & { password?: string }) => Promise<void>;
  updateUser: (id: string, data: Partial<User>) => Promise<void>;
  deleteUser: (id: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | null>(null);

const MOCK_USERS: User[] = [
  { id: '1', name: 'Admin User', email: 'admin@company.com', role: 'ADMIN', permissions: { views: DEFAULT_PERMISSIONS.ADMIN } },
];

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [users, setUsers] = useState<User[]>([]);

  useEffect(() => {
    async function initDb() {
      try {
        const count = await db.users.count();
        if (count === 0) {
          const derived = await derivePasswordHash('Admin@123');
          const seedUsers = MOCK_USERS.map(u => ({
            ...u,
            passwordHash: derived.hash,
            salt: derived.salt,
            iterations: derived.iterations,
          }));
          await db.users.bulkPut(seedUsers as import('../types/domain').User[]);
        } else {
          // Cleanup legacy mock users if they still exist
          const legacyIds = ['2', '3', '4'];
          for (const id of legacyIds) {
             const u = await db.users.get(id);
             if (u && ['ravi@company.com', 'aarti@company.com', 'viewer@company.com'].includes(u.email)) {
                 await db.users.delete(id);
             }
          }
        }
        const dbUsers = await db.users.toArray();

        // Ensure default permissions only if none are configured
        const updatedUsers: User[] = [];
        for (const u of dbUsers) {
          if (!u.permissions || !u.permissions.views || u.permissions.views.length === 0) {
            u.permissions = { views: DEFAULT_PERMISSIONS[u.role] || [] };
            await db.users.put(u);
          }
          updatedUsers.push({ 
            id: u.id, 
            name: u.name, 
            email: u.email, 
            role: u.role as Role, 
            permissions: u.permissions, 
            assignedExecutiveName: u.assignedExecutiveName,
            maintenanceMode: u.maintenanceMode,
          });
        }
        setUsers(updatedUsers);

      } catch (err) {
        console.error("Failed to init users DB", err);
      } finally {
        setLoading(false);
      }
    }
    initDb();
  }, []);

  const login = async (identifier: string, password: string): Promise<User> => {
    const searchStr = identifier.trim().toLowerCase();
    const found: import('../types/domain').User[] = await db.users.filter(u => 
      u.name.trim().toLowerCase() === searchStr || (!!u.email && u.email.trim().toLowerCase() === searchStr)
    ).first();

    if (!found) {
      throw new Error('Invalid credentials');
    }

    // Check account lockout
    if (found.lockoutUntil && new Date(found.lockoutUntil) > new Date()) {
      const waitSeconds = Math.ceil((new Date(found.lockoutUntil).getTime() - Date.now()) / 1000);
      throw new Error(`Account temporarily locked due to failed attempts. Please try again in ${waitSeconds}s.`);
    }

    const { isValid, needsRehash } = await verifyPassword(
      password,
      found.passwordHash,
      found.salt,
      found.iterations
    );

    if (!isValid) {
      const attempts = (found.failedLoginAttempts || 0) + 1;
      const updates: Partial<import('../types/domain').User> = { failedLoginAttempts: attempts };
      if (attempts >= 5) {
        // Lock for 60 seconds
        updates.lockoutUntil = new Date(Date.now() + 60000).toISOString();
      }
      await db.users.update(found.id, updates);
      throw new Error('Invalid credentials');
    }

    // Reset failed attempts & upgrade legacy hash to PBKDF2 if needed
    const updates: Partial<import('../types/domain').User> = {
      failedLoginAttempts: 0,
      lockoutUntil: null,
      lastLogin: new Date().toISOString(),
    };

    if (needsRehash) {
      const derived = await derivePasswordHash(password);
      updates.passwordHash = derived.hash;
      updates.salt = derived.salt;
      updates.iterations = derived.iterations;
    }

    await db.users.update(found.id, updates);

    const safeUser: User = { 
      id: found.id, 
      name: found.name, 
      email: found.email, 
      role: found.role as Role, 
      permissions: found.permissions || { views: DEFAULT_PERMISSIONS[found.role] || [] }, 
      assignedExecutiveName: found.assignedExecutiveName,
      maintenanceMode: found.maintenanceMode,
    };

    setUser(safeUser);
    return safeUser;
  };

  const logout = () => setUser(null);

  const hasPermission = (view: string) => {
    if (!user) return false;
    if (user.role === 'ADMIN' || view === 'connectivity_hub') return true;
    return user.permissions?.views?.includes(view) ?? false;
  };

  const isExecutive = () => user?.role === 'EXECUTIVE';

  const addUser = async (u: Omit<User, 'id'> & { password?: string }) => {
    const id = crypto.randomUUID();
    const pw = u.password || 'Admin@123';
    const derived = await derivePasswordHash(pw);
    const { password, ...userWithoutPassword } = u;

    const newUser = { 
      ...userWithoutPassword, 
      id, 
      passwordHash: derived.hash,
      salt: derived.salt,
      iterations: derived.iterations,
      createdAt: new Date().toISOString(),
    };

    setUsers(prev => [...prev, { ...userWithoutPassword, id }]);
    await db.users.put(newUser as import('../types/domain').User);
  };

  const updateUser = async (id: string, data: Partial<User> & { password?: string }) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, ...data } : u));
    const existing = await db.users.get(id);
    if (existing) {
      const updatePayload: Partial<import('../types/domain').User> = { ...existing, ...data };
      if (data.password) {
        const derived = await derivePasswordHash(data.password);
        updatePayload.passwordHash = derived.hash;
        updatePayload.salt = derived.salt;
        updatePayload.iterations = derived.iterations;
        delete updatePayload.password;
      }

      await db.users.update(id, updatePayload);

      // If name changed, ripple it through the database
      if (data.name && data.name !== existing.name) {
          const oldName = existing.name;
          const newName = data.name;

          // 1. Update loan_records
          const recordsToUpdate = await db.loan_records.filter(r => r.executive_name === oldName || r['Executive Name'] === oldName).toArray();
          if (recordsToUpdate.length > 0) {
              const updatedRecords = recordsToUpdate.map(r => ({ ...r, executive_name: newName, ['Executive Name']: newName }));
              await db.loan_records.bulkPut(updatedRecords);
          }

          // 2. Update customer_feedbacks
          const feedbacksToUpdate = await db.customer_feedbacks.where('agentId').equals(id).toArray();
          if (feedbacksToUpdate.length > 0) {
              const updatedFeedbacks = feedbacksToUpdate.map(f => ({ ...f, agentName: newName }));
              await db.customer_feedbacks.bulkPut(updatedFeedbacks);
          }

          // 3. Update attendance_logs
          const attendanceToUpdate = await db.attendance_logs.where('userId').equals(id).toArray();
          if (attendanceToUpdate.length > 0) {
              const updatedAttendance = attendanceToUpdate.map(a => ({ ...a, userName: newName }));
              await db.attendance_logs.bulkPut(updatedAttendance);
          }
      }
    }
  };

  const deleteUser = async (id: string) => {
    setUsers(prev => prev.filter(u => u.id !== id));
    await db.users.delete(id);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, hasPermission, isExecutive, users, addUser, updateUser, deleteUser }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be inside AuthProvider');
  return ctx;
};

import { createContext, useContext, useState, ReactNode, useCallback, useEffect, useMemo } from 'react';
import { parseMainFile, parsePaidFile, mergePaidIntoRecords, parseAdditionalFile, mergeAdditionalIntoRecords, parseCorrectedFile, mergeCorrectedIntoRecords } from '../lib/fileParser';
import { db, AuditEntry, UploadSession } from '../lib/db';
import { useAuth } from './AuthContext';
import { atomicFileImport, atomicUpdateLoanRecord, atomicBulkUpdateLoanRecords } from '../lib/repositories/loanRepository';
import { setTargetRecord, deleteTargetRecord } from '../lib/repositories/targetRepository';

interface DataStateContextType {
  isLoading: boolean;
  records: LoanRecord[];
  filteredRecords: LoanRecord[];
  schema: string[];
  targets: Record<string, number>;
  auditLog: AuditEntry[];
  uploadHistory: UploadSession[];
  globalBucket: string;
  canUndo: boolean;
  canRedo: boolean;
}

interface DataDispatchContextType {
  loadMainFile: (buffer: ArrayBuffer, fileName: string, userName: string) => Promise<{ rowCount: number }>;
  loadPaidFile: (buffer: ArrayBuffer, fileName: string, userName: string) => Promise<{ matched: number; total: number }>;
  loadAdditionalFile: (buffer: ArrayBuffer, fileName: string, userName: string) => Promise<{ matched: number; total: number; stats: any }>;
  loadCorrectedFile: (buffer: ArrayBuffer, fileName: string, userName: string) => Promise<{ matched: number; total: number }>;
  updateRecord: (agreementid: string, field: string, value: unknown, userName: string) => Promise<void>;
  bulkUpdateRecords: (updates: {agreementid: string, field: string, value: unknown}[], userName: string) => Promise<void>;
  setTarget: (key: string, pct: number, userName: string) => Promise<void>;
  undo: () => Promise<void>;
  redo: () => Promise<void>;
  setGlobalBucket: (val: string) => void;
}

interface DataContextType extends DataStateContextType, DataDispatchContextType {}

const DataStateContext = createContext<DataStateContextType | null>(null);
const DataDispatchContext = createContext<DataDispatchContextType | null>(null);

export function DataProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [records, setRecords] = useState<LoanRecord[]>([]);

  const [schema, setSchema] = useState<string[]>([]);
  const [targets, setTargets] = useState<Record<string, number>>({});
  const [auditLog, setAuditLog] = useState<AuditEntry[]>([]);
  const [uploadHistory, setUploadHistory] = useState<UploadSession[]>([]);
  const [globalBucket, setGlobalBucket] = useState<string>('ALL');
  const [isLoading, setIsLoading] = useState(true);

  const [undoStack, setUndoStack] = useState<{type: string, audits: AuditEntry[]}[]>([]);
  const [redoStack, setRedoStack] = useState<{type: string, audits: AuditEntry[]}[]>([]);

  useEffect(() => {
    if (records.length > 0) {
      const keys = new Set<string>();
      // To prevent extreme lag on 100k rows, we sample the first 500 rows. In CSV imports, columns are uniform.
      // But let's actually scan all of them because the user requested it. We'll use a fast loop.
      for (let i = 0; i < records.length; i++) {
        const keysArray = Object.keys(records[i]);
        for (let j = 0; j < keysArray.length; j++) {
          keys.add(keysArray[j]);
        }
      }
      setSchema(Array.from(keys));
    } else {
      setSchema([]);
    }
  }, [records]);

  // Load from Dexie on mount
  useEffect(() => {
    async function loadData() {
      // 1. Migrate legacy localStorage targets if present
      try {
        const savedTargetsStr = localStorage.getItem('app_targets');
        if (savedTargetsStr) {
          const savedTargets = JSON.parse(savedTargetsStr);
          for (const [key, pct] of Object.entries(savedTargets)) {
            // Check if it already exists in Dexie so we don't overwrite newer changes
            const existing = await db.state_targets.get(key);
            if (!existing) {
              await db.state_targets.put({ key, pct: Number(pct), updatedAt: new Date().toISOString() });
            }
          }
          // Intentionally NOT deleting from localStorage, just stop reading it as primary
        }
      } catch (err) {
        console.error("Migration error:", err);
      }

      // 2. Load targets from Dexie
      try {
        const dbTargets = await db.state_targets.toArray();
        const targetsMap = dbTargets.reduce((acc, t) => {
          acc[t.key] = t.pct;
          return acc;
        }, {} as Record<string, number>);
        setTargets(targetsMap);

        // 3. Load authorized records (Enforcing Executive Scope at Repository boundary)
        const { fetchAuthorizedLoanRecords } = await import('../lib/repositories/loanRepository');
        const dbRecords = await fetchAuthorizedLoanRecords(user);
        setRecords(dbRecords);

        // 4. Load history and audit logs
        const dbUploads = await db.upload_sessions.orderBy('createdAt').reverse().toArray();
        setUploadHistory(dbUploads);

        const dbAudit = await db.audit_log.orderBy('createdAt').reverse().toArray();
        setAuditLog(dbAudit);
      } catch (err) {
        console.error("Dexie Load Error:", err);
      } finally {
        setIsLoading(false);
      }
    }
    loadData();
  }, [user]);

  const loadMainFile = useCallback(async (buffer: ArrayBuffer, fileName: string, userName: string) => {
    const parsed = parseMainFile(buffer);
    const entry = { id: crypto.randomUUID(), type: 'MAIN_DATA', fileName, recordCount: parsed.length, uploadedBy: userName, createdAt: new Date().toISOString() };
    setUploadHistory(prev => [entry, ...prev]);

    await atomicFileImport(parsed, entry as UploadSession);

    const { fetchAuthorizedLoanRecords } = await import('../lib/repositories/loanRepository');
    const dbRecords = await fetchAuthorizedLoanRecords(user);
    setRecords(dbRecords);

    return { rowCount: parsed.length };
  }, [user]);

  const loadPaidFile = useCallback(async (buffer: ArrayBuffer, fileName: string, userName: string) => {
    const paidRows = parsePaidFile(buffer);
    let matched = 0;

    const allDbRecords = await db.loan_records.toArray();
    const mergedData = mergePaidIntoRecords(allDbRecords, paidRows);
    matched = paidRows.filter(p => allDbRecords.some(r => r.agreementid === p.agreementid)).length;

    const entry = { id: crypto.randomUUID(), type: 'PAID_FILE', fileName, recordCount: paidRows.length, uploadedBy: userName, createdAt: new Date().toISOString() };
    setUploadHistory(prev => [entry, ...prev]);

    await atomicFileImport(mergedData, entry as UploadSession);

    const { fetchAuthorizedLoanRecords } = await import('../lib/repositories/loanRepository');
    const dbRecords = await fetchAuthorizedLoanRecords(user);
    setRecords(dbRecords);

    return { matched, total: paidRows.length }; 
  }, [user]);

  const loadAdditionalFile = useCallback(async (buffer: ArrayBuffer, fileName: string, userName: string) => {
    const additionalRows = parseAdditionalFile(buffer);

    const allDbRecords = await db.loan_records.toArray();
    const { merged, stats } = mergeAdditionalIntoRecords(allDbRecords, additionalRows);
    const matched = additionalRows.filter(p => allDbRecords.some(r => r.agreementid === p.agreementid)).length;

    const entry = { id: crypto.randomUUID(), type: 'ADDITIONAL_COLLECTION_FILE', fileName, recordCount: additionalRows.length, uploadedBy: userName, createdAt: new Date().toISOString() };
    setUploadHistory(prev => [entry, ...prev]);

    await atomicFileImport(merged, entry as UploadSession);

    const { fetchAuthorizedLoanRecords } = await import('../lib/repositories/loanRepository');
    const dbRecords = await fetchAuthorizedLoanRecords(user);
    setRecords(dbRecords);

    return { matched, total: additionalRows.length, stats };
  }, [user]);

  const loadCorrectedFile = useCallback(async (buffer: ArrayBuffer, fileName: string, userName: string) => {
    const correctedRows = parseCorrectedFile(buffer);

    const allDbRecords = await db.loan_records.toArray();
    const { merged, matched } = mergeCorrectedIntoRecords(allDbRecords, correctedRows);

    const entry = { id: crypto.randomUUID(), type: 'CORRECTED_DAC_FILE', fileName, recordCount: correctedRows.length, uploadedBy: userName, createdAt: new Date().toISOString() };
    setUploadHistory(prev => [entry, ...prev]);

    await atomicFileImport(merged, entry as UploadSession);

    const { fetchAuthorizedLoanRecords } = await import('../lib/repositories/loanRepository');
    const dbRecords = await fetchAuthorizedLoanRecords(user);
    setRecords(dbRecords);

    return { matched, total: correctedRows.length };
  }, [user]);

  const updateRecord = useCallback(async (agreementid: string, field: string, value: unknown, userName: string) => {
    let oldVal = '';

    setRecords(prev => prev.map(r => {
      if (r.agreementid === agreementid) {
        oldVal = String(r[field] ?? '');
        return { ...r, [field]: value, [`${field}_source`]: 'MANUAL' };
      }
      return r;
    }));

    const audit = {
      id: crypto.randomUUID(),
      agreementid,
      field,
      oldValue: oldVal,
      newValue: String(value),
      changedBy: userName,
      createdAt: new Date().toISOString(),
      source: 'MANUAL',
    };

    setAuditLog(a => [audit, ...a]);

    await atomicUpdateLoanRecord(
      agreementid,
      { [field]: value, [`${field}_source`]: 'MANUAL' },
      { userName, userRole: user?.role || 'VIEWER', source: 'MANUAL' }
    );

    setUndoStack(prev => [...prev, { type: 'UPDATE', audits: [audit] }]);
    setRedoStack([]);
  }, [user]);


  const bulkUpdateRecords = useCallback(async (updates: {agreementid: string, field: string, value: unknown}[], userName: string) => {
    const newAudits: AuditEntry[] = [];
    const updateMap = new Map();

    updates.forEach(u => {
      if (!updateMap.has(u.agreementid)) {
        updateMap.set(u.agreementid, {});
      }
      updateMap.get(u.agreementid)[u.field] = u.value;
      updateMap.get(u.agreementid)[`${u.field}_source`] = 'MANUAL';
    });

    setRecords(prev => {
      const next = prev.map(r => {
        if (updateMap.has(r.agreementid)) {
          const u = updateMap.get(r.agreementid);

          Object.keys(u).forEach(key => {
            if (!key.endsWith('_source')) {
              newAudits.push({
                id: crypto.randomUUID(),
                agreementid: r.agreementid,
                field: key,
                oldValue: String(r[key] ?? ''),
                newValue: String(u[key]),
                changedBy: userName,
                createdAt: new Date().toISOString(),
                source: 'MANUAL',
              });
            }
          });

          return { ...r, ...u };
        }
        return r;
      });
      return next;
    });

    setAuditLog(a => [...newAudits, ...a]);

    const formattedUpdates = Array.from(updateMap.entries()).map(([agreementId, upds]) => ({
      agreementId,
      updates: upds
    }));

    await atomicBulkUpdateLoanRecords(
      formattedUpdates,
      { userName, userRole: user?.role || 'VIEWER', source: 'BULK_OPERATION' }
    );

    setUndoStack(prev => [...prev, { type: 'BULK_UPDATE', audits: newAudits }]);
    setRedoStack([]);
  }, [user]);

  const setTarget = useCallback(async (key: string, pct: number, userName: string) => {
    const actor = userName || user?.name || 'System';
    if (pct <= 0) {
      setTargets(prev => {
        const next = { ...prev };
        delete next[key];
        return next;
      });
      await deleteTargetRecord(key, actor);
    } else {
      setTargets(prev => ({ ...prev, [key]: pct }));
      await setTargetRecord(key, pct, actor);
    }
  }, [user]);


  const undo = useCallback(async () => {
    if (undoStack.length === 0) return;
    const action = undoStack[undoStack.length - 1];
    setUndoStack(prev => prev.slice(0, -1));
    setRedoStack(prev => [...prev, action]);

    const updateMap = new Map();
    action.audits.forEach(a => {
      if (!updateMap.has(a.agreementid)) updateMap.set(a.agreementid, {});
      updateMap.get(a.agreementid)[a.field] = a.oldValue;
      updateMap.get(a.agreementid)[`${a.field}_source`] = 'UNDO'; // Mark as undone
    });

    setRecords(prev => {
      return prev.map(r => {
        if (updateMap.has(r.agreementid)) {
          const u = updateMap.get(r.agreementid);
          return { ...r, ...u };
        }
        return r;
      });
    });

    if (updateMap.size > 0) {
      const formattedUpdates = Array.from(updateMap.entries()).map(([agreementId, upds]) => ({
        agreementId,
        updates: upds
      }));
      await atomicBulkUpdateLoanRecords(
        formattedUpdates,
        { userName: user?.name || 'Unknown', userRole: user?.role || 'VIEWER', source: 'MANUAL' }
      );
    }
  }, [undoStack, user]);

  const redo = useCallback(async () => {
    if (redoStack.length === 0) return;
    const action = redoStack[redoStack.length - 1];
    setRedoStack(prev => prev.slice(0, -1));
    setUndoStack(prev => [...prev, action]);

    const updateMap = new Map();
    action.audits.forEach(a => {
      if (!updateMap.has(a.agreementid)) updateMap.set(a.agreementid, {});
      updateMap.get(a.agreementid)[a.field] = a.newValue;
      updateMap.get(a.agreementid)[`${a.field}_source`] = 'MANUAL'; // Restore manual source
    });

    setRecords(prev => {
      return prev.map(r => {
        if (updateMap.has(r.agreementid)) {
          const u = updateMap.get(r.agreementid);
          return { ...r, ...u };
        }
        return r;
      });
    });

    if (updateMap.size > 0) {
      const formattedUpdates = Array.from(updateMap.entries()).map(([agreementId, upds]) => ({
        agreementId,
        updates: upds
      }));
      await atomicBulkUpdateLoanRecords(
        formattedUpdates,
        { userName: user?.name || 'Unknown', userRole: user?.role || 'VIEWER', source: 'MANUAL' }
      );
    }
  }, [redoStack, user]);

  const filteredRecords = useMemo(() => {
    if (!records) return [];
    if (globalBucket === 'ALL') return records;
    return records.filter((r: LoanRecord) => String(r.bom_bkt).trim().toUpperCase() === globalBucket);
  }, [records, globalBucket]);

  return (
    <DataDispatchContext.Provider value={useMemo(() => ({ undo, redo, loadMainFile, loadPaidFile, loadAdditionalFile, loadCorrectedFile, updateRecord, bulkUpdateRecords, setTarget, setGlobalBucket }), [undo, redo, loadMainFile, loadPaidFile, loadAdditionalFile, loadCorrectedFile, updateRecord, bulkUpdateRecords, setTarget, setGlobalBucket])}>
      <DataStateContext.Provider value={{ canUndo: undoStack.length > 0, canRedo: redoStack.length > 0, isLoading, records, filteredRecords, schema, targets, auditLog, uploadHistory, globalBucket }}>
        {children}
      </DataStateContext.Provider>
    </DataDispatchContext.Provider>
  );
}

export const useDataState = () => {
  const ctx = useContext(DataStateContext);
  if (!ctx) throw new Error('useDataState must be inside DataProvider');
  return ctx;
};

export const useDataDispatch = () => {
  const ctx = useContext(DataDispatchContext);
  if (!ctx) throw new Error('useDataDispatch must be inside DataProvider');
  return ctx;
};

export const useData = () => {
  const state = useDataState();
  const dispatch = useDataDispatch();
  return { ...state, ...dispatch };
};

import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { useAuth } from './AuthContext';
import {
  ConflictRecord,
  DeviceIdentity,
  DeviceSession,
  NetworkMode,
  PeerInfo,
  SyncStats
} from '../lib/sync/types';
import { syncEngine } from '../lib/sync/syncEngine';
import { backupManager } from '../lib/sync/backupManager';
import { getLocalDeviceIdentity, updateLocalDeviceName } from '../lib/sync/deviceIdentity';
import { resolveConflictRecord } from '../lib/sync/crdtEngine';
import { BackupSnapshotRecord, db } from '../lib/db';
import { toast } from 'sonner';

interface SyncContextType {
  identity: DeviceIdentity;
  peers: PeerInfo[];
  sessions: DeviceSession[];
  stats: SyncStats;
  conflicts: ConflictRecord[];
  backups: BackupSnapshotRecord[];
  isSyncing: boolean;
  scheduleBackupMinutes: number;
  // Actions
  triggerManualSync: () => Promise<void>;
  approvePeer: (peerId: string) => Promise<void>;
  rejectPeer: (peerId: string) => Promise<void>;
  disablePeer: (peerId: string) => Promise<void>;
  reEnablePeer: (peerId: string) => Promise<void>;
  removePeer: (peerId: string) => Promise<void>;
  resolveConflict: (conflictId: string, resolution: 'KEEP_LOCAL' | 'KEEP_REMOTE' | 'FIELD_MERGE' | 'MANUAL', customData?: any) => Promise<void>;
  createBackup: (label?: string) => Promise<void>;
  restoreBackup: (payload: string, mode: 'MERGE' | 'REPLACE') => Promise<void>;
  verifyBackup: (backupId: string) => Promise<{ valid: boolean; details: string }>;
  downloadBackup: (backupId: string) => Promise<void>;
  deleteBackup: (backupId: string) => Promise<void>;
  setNetworkMode: (mode: NetworkMode) => void;
  setScheduleBackupMinutes: (mins: number) => void;
  updateDeviceName: (name: string) => void;
  // WebRTC P2P Direct Pairing
  generatePairingOffer: (targetPeerId: string) => Promise<string>;
  acceptPairingOffer: (offerBase64: string) => Promise<string>;
  acceptPairingAnswer: (answerBase64: string) => Promise<void>;
  requestPairingFromPayload: (payload: string) => Promise<void>;
}

const SyncContext = createContext<SyncContextType | undefined>(undefined);

export function SyncProvider({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();
  const [identity, setIdentity] = useState<DeviceIdentity>(() => getLocalDeviceIdentity());
  const [peers, setPeers] = useState<PeerInfo[]>([]);
  const [sessions, setSessions] = useState<DeviceSession[]>([]);
  const [conflicts, setConflicts] = useState<ConflictRecord[]>([]);
  const [backups, setBackups] = useState<BackupSnapshotRecord[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [scheduleBackupMinutes, setScheduleBackupMinutesState] = useState<number>(() => backupManager.getScheduleInterval());

  const [stats, setStats] = useState<SyncStats>({
    totalPeers: 1,
    approvedPeers: 1,
    onlinePeers: 1,
    pendingApproval: 0,
    queuedChanges: 0,
    openConflicts: 0,
    syncInProgress: false,
    totalSyncedTransactions: 0,
    networkMode: 'ALL'
  });

  const refreshSyncData = useCallback(async () => {
    try {
      const allPeers = await syncEngine.getAllPeers();
      setPeers(allPeers);

      const liveSessions = syncEngine.getLiveSessions();
      setSessions(liveSessions);

      const currentStats = await syncEngine.getSyncStats();
      setStats(currentStats);

      const openConflicts = (await db.sync_conflicts.where('status').equals('OPEN').toArray()) as ConflictRecord[];
      setConflicts(openConflicts);

      const history = await backupManager.getBackupHistory();
      setBackups(history);
    } catch (e) {
      console.error('[SyncContext] refresh error', e);
    }
  }, []);

  useEffect(() => {
    syncEngine.init().then(() => {
      refreshSyncData();
    });

    const unsubscribe = syncEngine.subscribe(() => {
      refreshSyncData();
    });

    return () => {
      unsubscribe();
    };
  }, [refreshSyncData]);

  // Update current user session in sync engine when user logs in or out
  useEffect(() => {
    syncEngine.setCurrentUser(user ? { email: user.email, name: user.name, role: user.role } : null);
  }, [user]);

  const triggerManualSync = async () => {
    setIsSyncing(true);
    try {
      const count = await syncEngine.triggerGlobalSync();
      if (count > 0) {
        toast.success(`Sync dispatched across ${count} connected peer(s)`);
      } else {
        toast.info('No approved peers connected for mesh sync.');
      }
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Sync failed: ' + (e.message || 'Unknown error'));
    } finally {
      setIsSyncing(false);
    }
  };

  const approvePeer = async (peerId: string) => {
    try {
      await syncEngine.approvePeer(peerId, user?.name || 'Admin');
      toast.success('Peer device approved for CRM synchronization');
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Failed to approve peer: ' + e.message);
    }
  };

  const rejectPeer = async (peerId: string) => {
    try {
      await syncEngine.rejectPeer(peerId);
      toast.info('Peer device rejected');
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Failed to reject peer: ' + e.message);
    }
  };

  const disablePeer = async (peerId: string) => {
    try {
      await syncEngine.disablePeer(peerId);
      toast.warning('Peer device synchronization disabled');
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Failed to disable peer: ' + e.message);
    }
  };

  const reEnablePeer = async (peerId: string) => {
    try {
      await syncEngine.reEnablePeer(peerId);
      toast.success('Peer device re-enabled and synchronized');
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Failed to re-enable peer: ' + e.message);
    }
  };

  const removePeer = async (peerId: string) => {
    try {
      await syncEngine.removePeer(peerId);
      toast.success('Peer removed from registry');
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Failed to remove peer: ' + e.message);
    }
  };

  const resolveConflict = async (
    conflictId: string,
    resolution: 'KEEP_LOCAL' | 'KEEP_REMOTE' | 'FIELD_MERGE' | 'MANUAL',
    customData?: any
  ) => {
    try {
      await resolveConflictRecord(conflictId, resolution, customData, user?.name || 'Admin');
      toast.success(`Conflict resolved with strategy: ${resolution}`);
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Failed to resolve conflict: ' + e.message);
    }
  };

  const createBackup = async (label?: string) => {
    try {
      const snap = await backupManager.createBackup('MANUAL', label);
      toast.success(`Backup created: ${snap.checksum} (${snap.recordCounts.records} records)`);
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Failed to create backup: ' + e.message);
    }
  };

  const restoreBackup = async (payload: string, mode: 'MERGE' | 'REPLACE') => {
    try {
      const result = await backupManager.restoreBackupFromPayload(payload, mode);
      toast.success(`Backup restored successfully (${result.restoredRecords} records, ${result.restoredFeedbacks} feedbacks)`);
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Restore failed: ' + e.message);
    }
  };

  const verifyBackup = async (backupId: string) => {
    return await backupManager.verifyBackupIntegrity(backupId);
  };

  const downloadBackup = async (backupId: string) => {
    try {
      await backupManager.downloadBackupAsFile(backupId);
      toast.success('Backup file downloaded to local drive');
    } catch (e: Record<string, unknown>) {
      toast.error('Download failed: ' + e.message);
    }
  };

  const deleteBackup = async (backupId: string) => {
    try {
      await backupManager.deleteBackup(backupId);
      toast.info('Backup snapshot deleted');
      await refreshSyncData();
    } catch (e: Record<string, unknown>) {
      toast.error('Failed to delete backup: ' + e.message);
    }
  };

  const setNetworkMode = (mode: NetworkMode) => {
    syncEngine.getTransportManager().setNetworkMode(mode);
    setStats(prev => ({ ...prev, networkMode: mode }));
    toast.info(`P2P Network Mode set to: ${mode}`);
  };

  const setScheduleBackupMinutes = (mins: number) => {
    backupManager.setScheduleInterval(mins);
    setScheduleBackupMinutesState(mins);
    if (mins > 0) {
      toast.success(`Automated backups scheduled every ${mins} minutes`);
    } else {
      toast.info('Automated backup schedule disabled');
    }
  };

  const updateDeviceName = (name: string) => {
    const updated = updateLocalDeviceName(name);
    setIdentity(updated);
    toast.success(`Device name updated to: ${updated.deviceName}`);
    refreshSyncData();
  };

  const generatePairingOffer = async (targetPeerId: string) => {
    return await syncEngine.getTransportManager().getWebRTCTransport().createOfferForPeer(targetPeerId);
  };

  const acceptPairingOffer = async (offerBase64: string) => {
    return await syncEngine.getTransportManager().getWebRTCTransport().acceptOfferAndCreateAnswer(offerBase64);
  };

  const acceptPairingAnswer = async (answerBase64: string) => {
    await syncEngine.getTransportManager().getWebRTCTransport().acceptAnswer(answerBase64);
  };

  const requestPairingFromPayload = async (payload: string) => {
    await syncEngine.requestPairingFromPayload(payload);
  };

  return (
    <SyncContext.Provider
      value={{
        identity,
        peers,
        sessions,
        stats,
        conflicts,
        backups,
        isSyncing,
        scheduleBackupMinutes,
        triggerManualSync,
        approvePeer,
        rejectPeer,
        disablePeer,
        reEnablePeer,
        removePeer,
        resolveConflict,
        createBackup,
        restoreBackup,
        verifyBackup,
        downloadBackup,
        deleteBackup,
        setNetworkMode,
        setScheduleBackupMinutes,
        updateDeviceName,
        generatePairingOffer,
        acceptPairingOffer,
        acceptPairingAnswer,
        requestPairingFromPayload
      }}
    >
      {children}
    </SyncContext.Provider>
  );
}

