import * as XLSX from 'xlsx';
import { LoanRecord } from '../types/domain';

export function parseMainFile(fileBuffer: ArrayBuffer) {
  const wb = XLSX.read(fileBuffer, { type: 'array' });
  const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: null }) as LoanRecord[];

  return rows.map(row => ({
    ...row,
    agreementid: String(row['agreementid'] || row['AGREEMENTID'] || '').trim(),
    agreement_no: String(row['AGREEMENTNO'] || row['AGREEMENT_NO'] || row['Agreement No'] || row['agreement_no'] || row['loan_id'] || '').trim(),
    customer_name: String(row['CUSTOMERNAME'] || row['Customer Name'] || row['CUSTOMER_NAME'] || row['customer_name'] || row['customername'] || '').trim(),
    bom_bkt: parseInt(row['bom_bkt']) || 1,
    emi_amt: parseFloat(row['emi_amt']) || 0,
    principal_outstanding: parseFloat(row['principal_outstanding']) || 0,
    bcc_pending: parseFloat(row['bcc_pending']) || 0,
    penal_pending: parseFloat(row['penal_pending']) || 0,
    approx_forclosure: parseFloat(row['Approx Forclosure'] || row['approx_forclosure']) || 0,
    state: String(row['State'] || row['state'] || '').trim().toUpperCase(),
    city: String(row['City'] || row['city'] || '').trim().toUpperCase(),
    executive_name: String(row['Final EX. Name'] || row['Final EX. name'] || row['Final EX.NAME'] || row['EX. Name'] || row['EX. name'] || row['EX.NAME'] || row['Final Executive Name'] || row['final_executive_name'] || row['Final Executive'] || row['final_executive'] || row['Executive Name'] || row['executive_name'] || row['Executive'] || row['executive'] || '').trim(),
    allocation_date: row['Final Allocation Date'] || row['final_allocation_date'] || row['Allocation Date'] || row['allocation_date'] || row['AllocationDate'] || null,
    dac: parseFloat(row['DAC'] || row['dac']) || 0,
    ecs: parseFloat(row['ECS'] || row['ecs']) || 0,
    special: parseFloat(row['Special'] || row['special']) || 0,
    new_total: parseFloat(row['New Total'] || row['new_total']) || 0,
    settlement_approved_amt: row['Settlement Approved Amount'] != null ? parseFloat(row['Settlement Approved Amount']) : null,
    last_month_paid_flag: Boolean(row['Last Month Paid Flag'] || row['last_month_paid_flag']),
    dac_source: 'FILE' as const,
    ecs_source: 'FILE' as const,
    special_source: 'FILE' as const,
  })).filter(r => r.agreementid);
}

export function parsePaidFile(fileBuffer: ArrayBuffer) {
  const wb = XLSX.read(fileBuffer, { type: 'array' });
  const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: null }) as LoanRecord[];

  return rows.map(row => {
    const sfdc = parseFloat(row['SFDC'] || row['sfdc']) || 0;
    const online = parseFloat(row['Online'] || row['online']) || 0;
    return {
      agreementid: String(row['AGREEMENTID'] || row['agreementid'] || '').trim(),
      dac: sfdc + online,
      ecs: parseFloat(row['ECS'] || row['ecs']) || 0,
      special: parseFloat(row['Special Pres'] || row['Special'] || row['special']) || 0,
    };
  }).filter(r => r.agreementid);
}

export function mergePaidIntoRecords(existingRecords: LoanRecord[], paidRows: LoanRecord[]) {
  const paidMap: Record<string, unknown> = {};
  paidRows.forEach(r => { paidMap[r.agreementid] = r; });

  return existingRecords.map(rec => {
    const match = paidMap[String(rec.agreementid)];
    if (match) {
      let newProv = rec.provisional_dac;
      let is_conflict = rec.is_conflict || false;

      const rawProv = rec.provisional_dac_raw || rec.provisional_dac;
      if (rawProv && match.dac > 0) {
        if (rawProv === match.dac) {
          newProv = 0;
          is_conflict = false;
        } else {
          is_conflict = true;
        }
      }

      return {
        ...rec,
        ...match,
        dac: match.dac,
        ecs: match.ecs,
        special: match.special,
        dac_source: 'PAID_FILE',
        ecs_source: 'PAID_FILE',
        special_source: 'PAID_FILE',
        provisional_dac: newProv,
        is_conflict,
      };
    }
    return rec;
  });
}

export function parseAdditionalFile(fileBuffer: ArrayBuffer) {
  const wb = XLSX.read(fileBuffer, { type: 'array' });
  const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: null }) as LoanRecord[];

  const aggregated: Record<string, { amount: number, dates: string[], firstRow: any }> = {};

  rows.forEach(row => {
    const agreementid = String(row['AGREEMENTID'] || row['agreementid'] || row['Loan ID'] || row['loan_id'] || '').trim();
    if (!agreementid) return;

    // Attempt to read generic collection amount
    const amt = parseFloat(row['Amount'] || row['amount'] || row['Collection Amount'] || row['collection_amount'] || row['Collected'] || row['DAC'] || row['dac'] || row['Provisional Amount']) || 0;

    let dt = String(row['Date'] || row['date'] || row['Collection Date'] || row['collection_date'] || '').trim();
    if (!dt) dt = 'Unknown';

    if (!aggregated[agreementid]) aggregated[agreementid] = { amount: 0, dates: [], firstRow: row };
    aggregated[agreementid].amount += amt;
    if (dt !== 'Unknown' && !aggregated[agreementid].dates.includes(dt)) {
      aggregated[agreementid].dates.push(dt);
    }
  });

  return Object.entries(aggregated).map(([agreementid, data]) => ({
    ...data.firstRow,
    agreementid,
    provisional_dac: data.amount,
    collection_dates: data.dates.length > 0 ? data.dates.join(', ') : 'Unknown',
  }));
}

export function mergeAdditionalIntoRecords(existingRecords: LoanRecord[], additionalRows: LoanRecord[]) {
  const additionalMap: Record<string, unknown> = {};
  additionalRows.forEach(r => { additionalMap[r.agreementid] = r; });

  let newConflicts = 0;
  let newValidProv = 0;
  let alreadyCorrected = 0;
  let alreadyConfirmed = 0;

  const merged = existingRecords.map(rec => {
    const match = additionalMap[String(rec.agreementid)];
    if (match) {
      if (rec.dac_source === 'CORRECTED' || rec.is_corrected) {
        alreadyCorrected++;
        return rec; // Rule: REJECT/IGNORE already corrected records. Do not overwrite or recreate conflict.
      }

      let provisional_dac = match.provisional_dac;
      const currentConfirmedDac = rec.dac || 0;
      let is_conflict = false;

      if (currentConfirmedDac === provisional_dac && currentConfirmedDac > 0) {
        // Exact confirmation, so zero out provisional
        provisional_dac = 0;
        alreadyConfirmed++;
      } else if (currentConfirmedDac > 0 && currentConfirmedDac !== provisional_dac) {
        // Mismatch
        is_conflict = true;
        newConflicts++;
      } else {
        newValidProv++;
      }

      return {
        ...rec,
        ...match,
        provisional_dac: provisional_dac,
        provisional_dac_raw: match.provisional_dac, // store raw just in case
        provisional_collection_dates: match.collection_dates,
        is_conflict,
      };
    }
    return rec;
  });

  return { merged, stats: { newConflicts, newValidProv, alreadyCorrected, alreadyConfirmed, uniqueLoans: additionalRows.length } };
}

export function parseCorrectedFile(fileBuffer: ArrayBuffer) {
  const wb = XLSX.read(fileBuffer, { type: 'array' });
  const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: null }) as LoanRecord[];

  return rows.map(row => ({
    agreementid: String(row['AGREEMENTID'] || row['agreementid'] || row['Loan ID'] || row['loan_id'] || '').trim(),
    corrected_dac: parseFloat(row['Confirmed DAC'] || row['confirmed_dac'] || row['DAC'] || row['dac'] || row['Corrected DAC'] || row['corrected_dac']) || 0,
  })).filter(r => r.agreementid);
}

export function mergeCorrectedIntoRecords(existingRecords: LoanRecord[], correctedRows: LoanRecord[]) {
  const map: Record<string, unknown> = {};
  correctedRows.forEach(r => { map[r.agreementid] = r; });

  let matched = 0;
  const merged = existingRecords.map(rec => {
    const match = map[String(rec.agreementid)];
    if (match) {
      matched++;
      return {
        ...rec,
        ...match,
        dac: match.corrected_dac,
        dac_source: 'CORRECTED',
        is_corrected: true,
        provisional_dac: 0,
        is_conflict: false,
      };
    }
    return rec;
  });
  return { merged, matched, total: correctedRows.length };
}
export function detectColumns(fileBuffer: ArrayBuffer) {
  const wb = XLSX.read(fileBuffer, { type: 'array' });
  const sheet = wb.Sheets[wb.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(sheet, { defval: null }) as LoanRecord[];
  if (rows.length === 0) return { headers: [], rowCount: 0, sample: [] };
  const headers = Object.keys(rows[0]);
  return { headers, rowCount: rows.length, sample: rows.slice(0, 3) };
}

/**
 * Mahavtaar Ledger - Data Integrity Engine (Section 43 & Section 70)
 * Deeply scans the local Dexie database, validating schemas, relational integrity,
 * cryptographic hash chains, and financial consistency.
 */

import { db } from './db';
import { verifyAuditChainIntegrity } from './repositories/auditRepository';

export interface IntegrityCheckItem {
  id: string;
  name: string;
  category: 'FINANCIAL' | 'RELATIONAL' | 'CRYPTOGRAPHIC' | 'SYNC' | 'USER_ACCESS';
  status: 'PASSED' | 'WARNING' | 'FAILED';
  description: string;
  affectedCount: number;
  details?: string[];
  recommendation?: string;
}

export interface IntegrityReport {
  timestamp: string;
  overallScore: number; // 0 - 100
  overallStatus: 'HEALTHY' | 'WARNING' | 'CRITICAL';
  summary: {
    totalRecords: number;
    totalUsers: number;
    totalAudits: number;
    totalFeedbacks: number;
    totalAttendance: number;
    totalJournalEvents: number;
    totalConflicts: number;
  };
  checks: IntegrityCheckItem[];
  storageEstimate?: {
    usageBytes: number;
    quotaBytes: number;
    percentUsed: number;
  };
}

export async function runSystemIntegrityCheck(): Promise<IntegrityReport> {
  const checks: IntegrityCheckItem[] = [];

  // 1. Fetch raw data across stores
  const [
    loans,
    users,
    audits,
    feedbacks,
    attendance,
    journals,
    conflicts
  ] = await Promise.all([
    db.loan_records.toArray(),
    db.users.toArray(),
    db.audit_log.toArray(),
    db.customer_feedbacks.toArray(),
    db.attendance_logs.toArray(),
    db.sync_journal.toArray(),
    db.sync_conflicts.toArray()
  ]);

  const agreementIdSet = new Set(loans.map(l => l.agreementid).filter(Boolean));
  const userIdSet = new Set(users.map(u => u.id).filter(Boolean));

  // --- CHECK 1: Agreement IDs (Duplicates & Missing) ---
  const missingAgreements = loans.filter(l => !l.agreementid || String(l.agreementid).trim() === '');
  const idCounts = new Map<string, number>();
  loans.forEach(l => {
    if (l.agreementid) {
      idCounts.set(l.agreementid, (idCounts.get(l.agreementid) || 0) + 1);
    }
  });
  const duplicateAgreements = Array.from(idCounts.entries()).filter(([_, count]) => count > 1);

  if (missingAgreements.length > 0 || duplicateAgreements.length > 0) {
    checks.push({
      id: 'AGREEMENT_ID_VALIDITY',
      name: 'Agreement ID Uniqueness & Completeness',
      category: 'RELATIONAL',
      status: 'FAILED',
      description: 'Found missing or duplicate agreement IDs in loan records.',
      affectedCount: missingAgreements.length + duplicateAgreements.length,
      details: [
        ...missingAgreements.slice(0, 5).map(m => `Missing ID in record: ${m.customer_name || 'Unknown'}`),
        ...duplicateAgreements.slice(0, 5).map(([id, count]) => `Duplicate Agreement ID '${id}' (${count} occurrences)`)
      ],
      recommendation: 'Re-import or deduplicate loan base using Primary Agreement Key.'
    });
  } else {
    checks.push({
      id: 'AGREEMENT_ID_VALIDITY',
      name: 'Agreement ID Uniqueness & Completeness',
      category: 'RELATIONAL',
      status: 'PASSED',
      description: 'All loan records possess unique, valid primary agreement IDs.',
      affectedCount: 0
    });
  }

  // --- CHECK 2: Numeric Financial Fields & NaN check ---
  const invalidFinancialRecords: string[] = [];
  loans.forEach(l => {
    const rawPos = l.principal_outstanding !== undefined ? l.principal_outstanding : l.POS;
    const rawEmi = l.emi_amt !== undefined ? l.emi_amt : l.EMI;
    const rawDac = l.dac;
    const rawEcs = l.ecs;
    const rawSpecial = l.special;

    const pos = Number(rawPos ?? 0);
    const emi = Number(rawEmi ?? 0);
    const dac = Number(rawDac ?? 0);
    const ecs = Number(rawEcs ?? 0);
    const special = Number(rawSpecial ?? 0);

    const hasNaN = Number.isNaN(pos) || Number.isNaN(emi) || Number.isNaN(dac) || Number.isNaN(ecs) || Number.isNaN(special);
    const hasNegative = pos < 0 || emi < 0 || dac < 0 || ecs < 0 || special < 0;

    if (hasNaN || hasNegative) {
      invalidFinancialRecords.push(l.agreementid || 'Unknown');
    }
  });

  if (invalidFinancialRecords.length > 0) {
    checks.push({
      id: 'FINANCIAL_VALUES_NUMERIC',
      name: 'Financial Numbers & Non-Negative Invariant',
      category: 'FINANCIAL',
      status: 'WARNING',
      description: 'Found loan records with non-numeric or negative values in core financial columns.',
      affectedCount: invalidFinancialRecords.length,
      details: invalidFinancialRecords.slice(0, 5).map(id => `Record ${id} has invalid financial metrics`),
      recommendation: 'Normalize values via the Data Cleaning / Re-import tool.'
    });
  } else {
    checks.push({
      id: 'FINANCIAL_VALUES_NUMERIC',
      name: 'Financial Numbers & Non-Negative Invariant',
      category: 'FINANCIAL',
      status: 'PASSED',
      description: 'All loan record POS, EMI, and Collection numbers are valid non-negative values.',
      affectedCount: 0
    });
  }

  // --- CHECK 3: Cryptographic Audit Hash Chain ---
  const auditVerification = await verifyAuditChainIntegrity();
  if (!auditVerification.valid) {
    checks.push({
      id: 'AUDIT_HASH_CHAIN',
      name: 'Cryptographic Audit Trail Integrity',
      category: 'CRYPTOGRAPHIC',
      status: 'FAILED',
      description: `Audit log hash chain validation failed: ${auditVerification.message}`,
      affectedCount: 1,
      recommendation: 'Investigate potential database tampering or historical record deletion.'
    });
  } else {
    checks.push({
      id: 'AUDIT_HASH_CHAIN',
      name: 'Cryptographic Audit Trail Integrity',
      category: 'CRYPTOGRAPHIC',
      status: 'PASSED',
      description: `All ${auditVerification.totalEntries} audit entries form a continuous, untampered SHA-256 hash chain.`,
      affectedCount: 0
    });
  }

  // --- CHECK 4: Orphan Customer Feedbacks ---
  const orphanFeedbacks = feedbacks.filter(fb => fb.agreementid && !agreementIdSet.has(fb.agreementid));
  if (orphanFeedbacks.length > 0 && loans.length > 0) {
    checks.push({
      id: 'ORPHAN_FEEDBACKS',
      name: 'Customer Feedback Relational Integrity',
      category: 'RELATIONAL',
      status: 'WARNING',
      description: 'Customer feedbacks reference agreement IDs that do not exist in the current loan dataset.',
      affectedCount: orphanFeedbacks.length,
      details: orphanFeedbacks.slice(0, 5).map(fb => `Feedback ${fb.id} references missing Agreement ${fb.agreementid}`),
      recommendation: 'Ensure all historical cases are loaded in the base dataset.'
    });
  } else {
    checks.push({
      id: 'ORPHAN_FEEDBACKS',
      name: 'Customer Feedback Relational Integrity',
      category: 'RELATIONAL',
      status: 'PASSED',
      description: 'All logged customer feedbacks map to valid loan records.',
      affectedCount: 0
    });
  }

  // --- CHECK 5: Orphan Attendance Logs ---
  const orphanAttendance = attendance.filter(att => att.userId && !userIdSet.has(att.userId));
  if (orphanAttendance.length > 0 && users.length > 0) {
    checks.push({
      id: 'ORPHAN_ATTENDANCE',
      name: 'Attendance User Relational Integrity',
      category: 'USER_ACCESS',
      status: 'WARNING',
      description: 'Attendance records reference deleted or non-existent user accounts.',
      affectedCount: orphanAttendance.length,
      recommendation: 'Archive user accounts instead of deleting them to preserve attendance audits.'
    });
  } else {
    checks.push({
      id: 'ORPHAN_ATTENDANCE',
      name: 'Attendance User Relational Integrity',
      category: 'USER_ACCESS',
      status: 'PASSED',
      description: 'All attendance logs correspond to active system users.',
      affectedCount: 0
    });
  }

  // --- CHECK 6: Unresolved CRDT Conflicts ---
  const openConflicts = conflicts.filter(c => c.status === 'OPEN');
  if (openConflicts.length > 0) {
    checks.push({
      id: 'UNRESOLVED_CRDT_CONFLICTS',
      name: 'Sync Conflict Quarantine Status',
      category: 'SYNC',
      status: 'WARNING',
      description: `There are ${openConflicts.length} quarantined financial conflict(s) requiring manual admin resolution.`,
      affectedCount: openConflicts.length,
      details: openConflicts.slice(0, 5).map(c => `Conflict on table ${c.tableName} (Record: ${c.recordId})`),
      recommendation: 'Review and resolve conflicting edits in the P2P Sync Hub.'
    });
  } else {
    checks.push({
      id: 'UNRESOLVED_CRDT_CONFLICTS',
      name: 'Sync Conflict Quarantine Status',
      category: 'SYNC',
      status: 'PASSED',
      description: 'No unresolved or quarantined sync conflicts detected.',
      affectedCount: 0
    });
  }

  // --- CHECK 7: User Security & Passwords ---
  const usersWithPlaintext = users.filter(u => (u as any).plainPassword);
  if (usersWithPlaintext.length > 0) {
    checks.push({
      id: 'USER_SECURITY_CREDENTIALS',
      name: 'User Password Encryption (PBKDF2)',
      category: 'USER_ACCESS',
      status: 'FAILED',
      description: 'Found user accounts storing legacy plaintext credentials.',
      affectedCount: usersWithPlaintext.length,
      recommendation: 'Re-save user profiles to upgrade credentials to PBKDF2-HMAC-SHA256.'
    });
  } else {
    checks.push({
      id: 'USER_SECURITY_CREDENTIALS',
      name: 'User Password Encryption (PBKDF2)',
      category: 'USER_ACCESS',
      status: 'PASSED',
      description: 'All user credentials use salted PBKDF2-HMAC-SHA256 cryptographic hashes.',
      affectedCount: 0
    });
  }

  // Calculate Overall Score
  let failCount = 0;
  let warnCount = 0;
  checks.forEach(c => {
    if (c.status === 'FAILED') failCount++;
    if (c.status === 'WARNING') warnCount++;
  });

  const penalty = (failCount * 25) + (warnCount * 8);
  const overallScore = Math.max(0, 100 - penalty);
  const overallStatus = failCount > 0 ? 'CRITICAL' : warnCount > 0 ? 'WARNING' : 'HEALTHY';

  // Storage estimation if supported
  let storageEstimate: IntegrityReport['storageEstimate'] = undefined;
  if (navigator.storage && navigator.storage.estimate) {
    try {
      const est = await navigator.storage.estimate();
      const usage = est.usage || 0;
      const quota = est.quota || 1;
      storageEstimate = {
        usageBytes: usage,
        quotaBytes: quota,
        percentUsed: Math.round((usage / quota) * 100),
      };
    } catch {
      // Storage estimate not supported
    }
  }

  return {
    timestamp: new Date().toISOString(),
    overallScore,
    overallStatus,
    summary: {
      totalRecords: loans.length,
      totalUsers: users.length,
      totalAudits: audits.length,
      totalFeedbacks: feedbacks.length,
      totalAttendance: attendance.length,
      totalJournalEvents: journals.length,
      totalConflicts: conflicts.length
    },
    checks,
    storageEstimate
  };
}

/**
 * Mahavtaar Ledger - Customer Feedback Repository
 * Data access and mutation layer for CustomerFeedback entities with audit and sync journaling.
 */

import { db, CustomerFeedback } from '../db';
import { incrementLamportClock } from '../sync/journal';
import { getLocalDeviceIdentity } from '../sync/deviceIdentity';
import { ValidationError } from '../errors';

export interface FeedbackMutationContext {
  actorUserId?: string;
  actorName: string;
  actorRole: string;
}

export async function getFeedbackByAgreementId(agreementid: string): Promise<CustomerFeedback[]> {
  return await db.customer_feedbacks.where('agreementid').equals(agreementid).reverse().sortBy('createdAt');
}

export async function getAllFeedbacks(): Promise<CustomerFeedback[]> {
  return await db.customer_feedbacks.reverse().sortBy('createdAt');
}

export async function submitCustomerFeedback(
  feedbackData: Omit<CustomerFeedback, 'id' | 'createdAt'> & { id?: string },
  ctx: FeedbackMutationContext
): Promise<CustomerFeedback> {
  if (!feedbackData.agreementid) {
    throw new ValidationError('Agreement ID is required for customer feedback.');
  }

  const feedbackId = feedbackData.id || `FB-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;
  const timestamp = new Date().toISOString();

  const record: CustomerFeedback = {
    ...feedbackData,
    id: feedbackId,
    createdAt: timestamp,
  };

  await db.transaction('rw', [db.customer_feedbacks, db.audit_log, db.sync_journal], async () => {
    await db.customer_feedbacks.put(record);

    await db.audit_log.add({
      id: crypto.randomUUID(),
      agreementid: feedbackData.agreementid,
      field: 'FEEDBACK_SUBMITTED',
      oldValue: '',
      newValue: JSON.stringify({
        status: record.status,
        disposition: (record as any).disposition,
        ptpDate: record.ptpDate,
        amountPaid: record.amountPaid,
      }),
      changedBy: ctx.actorName,
      createdAt: timestamp,
      source: 'CUSTOMER_FEEDBACK',
    });

    const lamport = incrementLamportClock();
    const device = getLocalDeviceIdentity();

    await db.sync_journal.add({
      id: crypto.randomUUID(),
      timestamp,
      lamport,
      tableName: 'customer_feedbacks',
      recordId: feedbackId,
      action: 'INSERT',
      data: record,
      peerId: device.peerId,
      deviceId: device.deviceId,
      status: 'QUEUED',
      hash: crypto.randomUUID(),
    });
  });

  return record;
}

import { ConnectionType, SyncMessageEnvelope } from '../types';

export interface TransportEventHandler {
  onMessage: (message: SyncMessageEnvelope) => void;
  onPeerConnected?: (peerId: string, type: ConnectionType, metadata?: any) => void;
  onPeerDisconnected?: (peerId: string) => void;
  onError?: (err: Error) => void;
}

export interface TransportAdapter {
  readonly type: ConnectionType;
  readonly name: string;
  isSupported(): boolean;
  init(handler: TransportEventHandler): Promise<void>;
  send(targetPeerId: string, message: SyncMessageEnvelope): Promise<boolean>;
  broadcast(message: SyncMessageEnvelope): Promise<boolean>;
  disconnect(): Promise<void>;
  getStatus(): { active: boolean; connectedPeers: string[] };
}

import React, { useState, useMemo } from 'react';
import { AppLayout } from '../components/layout/AppLayout';
